Payload = Annotated[FileSecret, {"description":"Synthetic deployment input"}]
def blueprint(payload: Payload):
    secret = payload
    entry = f'source /opt/root/bin/thisroot.sh\npython3 -m pip install --quiet magnus-sdk==0.8.2\npython3 - <<\'LLP_PROBE\'\nimport hashlib,json,os,pathlib,subprocess,shutil,urllib.request\nimport magnus\np=magnus.download_file({secret!r},target_path="/magnus/workspace/payload.txt")\nassert pathlib.Path(p).read_text()=="LLP-AGI deployment roundtrip; no physics events.\\n"\nr={{"success":True,"tool":\'collider\',"sdk":magnus.__version__,"physics_events":0}}\nassert json.loads(urllib.request.urlopen(os.environ["MAGNUS_ADDRESS"]+"/health").read())["status"]=="ok"\nimport ROOT\nr["ROOT"]=ROOT.gROOT.GetVersion()\nr["MG5"]=str(pathlib.Path(os.environ["MG5_DIR"])/"bin/mg5_aMC")\nassert pathlib.Path(r["MG5"]).is_file()\nassert pathlib.Path(os.environ["MG5_DIR"],"Delphes/DelphesHepMC2").is_file()\nr["DelphesHepMC2"]=True\nr["Pythia8"]=subprocess.check_output(["pythia8-config","--version"],text=True).strip()\nout=pathlib.Path("/magnus/workspace/probe.json")\nout.write_text(json.dumps(r,indent=2))\nsecret=magnus.custody_file(str(out),max_downloads=3)\npathlib.Path(os.environ["MAGNUS_RESULT"]).write_text(json.dumps({{"success":True,"output":secret}}))\n\nLLP_PROBE'
    submit_job(task_name="Deployment probe collider", namespace="HET-AGI", repo_name="ColliderAgent", branch="main", commit_sha="1140f39e8730889422a64a141fbd3ca10529e13b", container_image="docker://git.pku.edu.cn/het-agi/collider@sha256:1bf6d8db2cb9348f965c3c6650f1c6af8234c1d8be0b49040ddd55e79a33c1a5", cpu_count=4, memory_demand="8G", system_entry_command='', entry_command=entry)
